create extension if not exists "pgcrypto";
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, active boolean not null default true, created_at timestamptz not null default now());
create table public.links (id uuid primary key default gen_random_uuid(), title text not null, subtitle text, url text not null, icon text, category_id uuid references public.categories(id) on delete set null, sort_order integer not null default 0, active boolean not null default true, featured boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, short_description text not null, description text, image_url text, price numeric(12,2), old_price numeric(12,2), checkout_url text, category_id uuid references public.categories(id) on delete set null, featured boolean not null default false, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.projects (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, description text, image_url text, status text not null default 'draft', category_id uuid references public.categories(id) on delete set null, featured boolean not null default false, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.banners (id uuid primary key default gen_random_uuid(), title text not null, subtitle text, image_url text, cta_text text, cta_url text, active boolean not null default true, created_at timestamptz not null default now());
create table public.social_links (id uuid primary key default gen_random_uuid(), platform text not null unique, url text not null, active boolean not null default true, created_at timestamptz not null default now());
create table public.site_settings (id uuid primary key default gen_random_uuid(), key text not null unique, value jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create or replace function public.set_updated_at() returns trigger language plpgsql security invoker as $$ begin new.updated_at = now(); return new; end; $$;
create trigger products_updated before update on public.products for each row execute function public.set_updated_at();
create trigger links_updated before update on public.links for each row execute function public.set_updated_at();
create trigger projects_updated before update on public.projects for each row execute function public.set_updated_at();
create trigger settings_updated before update on public.site_settings for each row execute function public.set_updated_at();
alter table public.categories enable row level security; alter table public.links enable row level security; alter table public.products enable row level security; alter table public.projects enable row level security; alter table public.banners enable row level security; alter table public.social_links enable row level security; alter table public.site_settings enable row level security;
create policy "public reads active categories" on public.categories for select using (active); create policy "public reads active links" on public.links for select using (active); create policy "public reads active products" on public.products for select using (active); create policy "public reads active projects" on public.projects for select using (active); create policy "public reads active banners" on public.banners for select using (active); create policy "public reads active social links" on public.social_links for select using (active); create policy "public reads settings" on public.site_settings for select using (true);
create policy "authenticated manage categories" on public.categories for all to authenticated using (true) with check (true); create policy "authenticated manage links" on public.links for all to authenticated using (true) with check (true); create policy "authenticated manage products" on public.products for all to authenticated using (true) with check (true); create policy "authenticated manage projects" on public.projects for all to authenticated using (true) with check (true); create policy "authenticated manage banners" on public.banners for all to authenticated using (true) with check (true); create policy "authenticated manage social links" on public.social_links for all to authenticated using (true) with check (true); create policy "authenticated manage settings" on public.site_settings for all to authenticated using (true) with check (true);
insert into public.categories (name,slug,description) values ('Elevon Digital','digital','Produtos e soluções digitais'),('Elevon Engenharia','engenharia','Engenharia, planejamento e dados'),('Elevon AI','ai','Inteligência Artificial e automações'),('Elevon Academy','academy','Cursos e desenvolvimento'),('Elevon Labs','labs','Softwares, sistemas e inovação');
insert into storage.buckets (id,name,public) values ('products','products',true),('projects','projects',true),('banners','banners',true),('site','site',true) on conflict (id) do nothing;
create policy "public reads Elevon media" on storage.objects for select using (bucket_id in ('products','projects','banners','site')); create policy "authenticated manages Elevon media" on storage.objects for all to authenticated using (bucket_id in ('products','projects','banners','site')) with check (bucket_id in ('products','projects','banners','site'));
